  1→"use client";
  2→
  3→import { useRef, useState } from "react";
  4→import { Download, Save, Upload } from "lucide-react";
  5→import type { AdminRequestSheetRow } from "@/lib/types";
  6→
  7→type AdminRequestSheetProps = {
  8→  initialRows: AdminRequestSheetRow[];
  9→};
 10→
 11→const EDITABLE_COLUMNS: Array<{
 12→  key: keyof Omit<AdminRequestSheetRow, "requestId" | "college" | "deptName">;
 13→  label: string;
 14→  multiline?: boolean;
 15→}> = [
 16→  { key: "fieldName", label: "(최종) 초빙분야" },
 17→  { key: "hiringType", label: "채용구분" },
 18→  { key: "priority", label: "우선순위" },
 19→  { key: "requestedCount", label: "요청 인원" },
 20→  { key: "allocationResult", label: "배정 인원" },
 21→  { key: "status", label: "현재 단계" },
 22→  { key: "nextAction", label: "현재 필요 조치", multiline: true },
 23→  { key: "requestedGeneral", label: "요청 일반" },
 24→  { key: "requestedDedicated", label: "요청 전담" },
 25→  { key: "requestedForeign", label: "요청 외" },
 26→  { key: "kriFieldName", label: "KRI 분야", multiline: true },
 27→  { key: "hiringReason", label: "채용 사유", multiline: true },
 28→  { key: "deptRequestReason", label: "학과 요청 사유", multiline: true },
 29→  { key: "subjectAssignment", label: "과목 배정", multiline: true },
 30→  { key: "meetingNotes", label: "회의 메모", multiline: true },
 31→  { key: "notes", label: "비고", multiline: true },
 32→];
 33→
 34→function buildPayload(row: AdminRequestSheetRow) {
 35→  return {
 36→    fieldName: row.fieldName,
 37→    hiringType: row.hiringType,
 38→    priority: row.priority,
 39→    requestedCount: row.requestedCount,
 40→    allocationResult: row.allocationResult,
 41→    status: row.status,
 42→    nextAction: row.nextAction,
 43→    requestedGeneral: row.requestedGeneral,
 44→    requestedDedicated: row.requestedDedicated,
 45→    requestedForeign: row.requestedForeign,
 46→    kriFieldName: row.kriFieldName,
 47→    hiringReason: row.hiringReason,
 48→    deptRequestReason: row.deptRequestReason,
 49→    subjectAssignment: row.subjectAssignment,
 50→    meetingNotes: row.meetingNotes,
 51→    notes: row.notes,
 52→  };
 53→}
 54→
 55→export function AdminRequestSheet({ initialRows }: AdminRequestSheetProps) {
 56→  const [rows, setRows] = useState(initialRows);
 57→  const [message, setMessage] = useState("");
 58→  const [uploading, setUploading] = useState(false);
 59→  const [savingAll, setSavingAll] = useState(false);
 60→  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
 61→  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});
 62→
 63→  function markDirty(requestId: number) {
 64→    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
 65→  }
 66→
 67→  function updateCell(rowIndex: number, columnKey: (typeof EDITABLE_COLUMNS)[number]["key"], value: string) {
 68→    setRows((current) =>
 69→      current.map((item, index) => (index === rowIndex ? { ...item, [columnKey]: value } : item)),
 70→    );
 71→    markDirty(rows[rowIndex].requestId);
 72→  }
 73→
 74→  function focusCell(rowIndex: number, columnIndex: number) {
 75→    const key = `${rowIndex}:${columnIndex}`;
 76→    cellRefs.current[key]?.focus();
 77→  }
 78→
 79→  function handlePaste(
 80→    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 81→    rowIndex: number,
 82→    columnIndex: number,
 83→  ) {
 84→    const text = event.clipboardData.getData("text");
 85→    if (!text.includes("\t") && !text.includes("\n")) return;
 86→
 87→    event.preventDefault();
 88→    const matrix = text
 89→      .replace(/\r/g, "")
 90→      .split("\n")
 91→      .filter((line) => line.length > 0)
 92→      .map((line) => line.split("\t"));
 93→
 94→    setRows((current) =>
 95→      current.map((row, currentRowIndex) => {
 96→        const pastedRow = matrix[currentRowIndex - rowIndex];
 97→        if (!pastedRow) return row;
 98→
 99→        const nextRow = { ...row };
100→        pastedRow.forEach((cellValue, offset) => {
101→          const column = EDITABLE_COLUMNS[columnIndex + offset];
102→          if (!column) return;
103→          nextRow[column.key] = cellValue;
104→        });
105→        return nextRow;
106→      }),
107→    );
108→
109→    const touchedIds = matrix
110→      .map((_, offset) => rows[rowIndex + offset]?.requestId)
111→      .filter((value): value is number => Boolean(value));
112→    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
113→  }
114→
115→  function handleKeyDown(
116→    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
117→    rowIndex: number,
118→    columnIndex: number,
119→  ) {
120→    if (event.key === "ArrowRight") {
121→      event.preventDefault();
122→      focusCell(rowIndex, Math.min(columnIndex + 1, EDITABLE_COLUMNS.length - 1));
123→    } else if (event.key === "ArrowLeft") {
124→      event.preventDefault();
125→      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
126→    } else if (event.key === "ArrowDown") {
127→      event.preventDefault();
128→      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
129→    } else if (event.key === "ArrowUp") {
130→      event.preventDefault();
131→      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
132→    } else if (event.key === "Tab" && !event.shiftKey) {
133→      event.preventDefault();
134→      const nextColumnIndex = columnIndex + 1;
135→      if (nextColumnIndex < EDITABLE_COLUMNS.length) {
136→        focusCell(rowIndex, nextColumnIndex);
137→      } else if (rowIndex < rows.length - 1) {
138→        focusCell(rowIndex + 1, 0);
139→      }
140→    } else if (event.key === "Tab" && event.shiftKey) {
141→      event.preventDefault();
142→      const prevColumnIndex = columnIndex - 1;
143→      if (prevColumnIndex >= 0) {
144→        focusCell(rowIndex, prevColumnIndex);
145→      } else if (rowIndex > 0) {
146→        focusCell(rowIndex - 1, EDITABLE_COLUMNS.length - 1);
147→      }
148→    }
149→  }
150→
151→  async function handleSaveRow(rowIndex: number) {
152→    const row = rows[rowIndex];
153→    const response = await fetch("/api/admin/request-sheet", {
154→      method: "PATCH",
155→      headers: { "Content-Type": "application/json" },
156→      body: JSON.stringify({ requestId: row.requestId, values: buildPayload(row) }),
157→    });
158→    const data = (await response.json().catch(() => ({}))) as { message?: string };
159→    setMessage(response.ok ? "DB 연동 편집 시트를 저장했습니다." : data.message ?? "저장에 실패했습니다.");
160→    if (response.ok) {
161→      setDirtyIds((current) => current.filter((id) => id !== row.requestId));
162→    }
163→  }
164→
165→  async function handleSaveAll() {
166→    if (!dirtyIds.length) {
167→      setMessage("저장할 변경 사항이 없습니다.");
168→      return;
169→    }
170→
171→    setSavingAll(true);
172→    for (const requestId of dirtyIds) {
173→      const rowIndex = rows.findIndex((row) => row.requestId === requestId);
174→      if (rowIndex !== -1) {
175→        await handleSaveRow(rowIndex);
176→      }
177→    }
178→    setSavingAll(false);
179→    setMessage("변경한 항목을 모두 저장했습니다.");
180→  }
181→
182→  async function handleImport(event: React.ChangeEvent<HTMLInputElement>) {
183→    const file = event.target.files?.[0];
184→    if (!file) return;
185→
186→    setUploading(true);
187→    const formData = new FormData();
188→    formData.set("file", file);
189→
190→    const response = await fetch("/api/admin/request-sheet/import", {
191→      method: "POST",
192→      body: formData,
193→    });
194→    const data = (await response.json().catch(() => ({}))) as { message?: string; count?: number };
195→    if (response.ok) {
196→      setMessage(`엑셀 업로드를 반영했습니다. ${data.count ?? 0}개 항목을 갱신했습니다.`);
197→      window.location.reload();
198→      return;
199→    }
200→
201→    setMessage(data.message ?? "엑셀 업로드에 실패했습니다.");
202→    setUploading(false);
203→  }
204→
205→  return (
206→    <div>
207→      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
208→        <div className="flex flex-wrap gap-2">
209→          <button
210→            type="button"
211→            onClick={() => window.location.assign("/api/admin/request-sheet/export")}
212→            className="inline-flex items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-sm text-[#374151]"
213→          >
214→            <Download className="h-4 w-4" />
215→            엑셀 다운로드
216→          </button>
217→          <label className="inline-flex cursor-pointer items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-[#f9fafb] px-4 py-2 text-sm text-[#374151]">
218→            <Upload className="h-4 w-4" />
219→            {uploading ? "업로드 중..." : "엑셀 업로드"}
220→            <input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={handleImport} />
221→          </label>
222→          <button
223→            type="button"
224→            onClick={handleSaveAll}
225→            disabled={savingAll}
226→            className="inline-flex items-center gap-2 rounded-[10px] border border-[#6a7f48] bg-[#394727] px-4 py-2 text-sm text-[#f3f1d4] disabled:opacity-60"
227→          >
228→            <Save className="h-4 w-4" />
229→            {savingAll ? "일괄 저장 중..." : `변경행 일괄 저장 (${dirtyIds.length})`}
230→          </button>
231→        </div>
232→        <p className="text-sm text-[#6b7280]">
233→          엑셀이나 구글시트에서 범위를 복사해 붙여넣으면 여러 칸을 한 번에 반영할 수 있습니다.
234→        </p>
235→      </div>
236→
237→      {message ? <p className="mb-4 rounded-[10px] bg-[#f0f9f4] px-4 py-3 text-sm text-[#374151]">{message}</p> : null}
238→
239→      <div className="max-h-[72vh] overflow-auto">
240→        <table className="min-w-[2800px] border-separate border-spacing-0 text-sm">
241→          <thead>
242→            <tr>
243→              {["소속대학", "학과명", ...EDITABLE_COLUMNS.map((column) => column.label), "저장"].map((label, index) => (
244→                <th
245→                  key={label}
246→                  className={`sticky top-0 ${index === 0 ? "left-0 z-[15]" : "z-[10]"} border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]`}
247→                  style={{ minWidth: label === "저장" ? 140 : 220 }}
248→                >
249→                  {label}
250→                </th>
251→              ))}
252→            </tr>
253→          </thead>
254→          <tbody>
255→            {rows.map((row, rowIndex) => (
256→              <tr key={row.requestId} className={rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]"}>
257→                <td className={`sticky left-0 z-[5] border-b border-r border-[#f0f0f0] px-4 py-3 ${rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]"}`}>{row.college}</td>
258→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.deptName}</td>
259→                {EDITABLE_COLUMNS.map((column, columnIndex) => (
260→                  <td key={`${row.requestId}-${column.key}`} className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top">
261→                    {column.multiline ? (
262→                      <textarea
263→                        ref={(node) => {
264→                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
265→                        }}
266→                        rows={4}
267→                        value={String(row[column.key] ?? "")}
268→                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
269→                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
270→                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
271→                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
272→                      />
273→                    ) : (
274→                      <input
275→                        ref={(node) => {
276→                          cellRefs.current[`${rowIndex}:${columnIndex}`] = node;
277→                        }}
278→                        type="text"
279→                        value={String(row[column.key] ?? "")}
280→                        onChange={(event) => updateCell(rowIndex, column.key, event.target.value)}
281→                        onPaste={(event) => handlePaste(event, rowIndex, columnIndex)}
282→                        onKeyDown={(event) => handleKeyDown(event, rowIndex, columnIndex)}
283→                        className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
284→                      />
285→                    )}
286→                  </td>
287→                ))}
288→                <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">
289→                  <button
290→                    type="button"
291→                    onClick={() => handleSaveRow(rowIndex)}
292→                    className="rounded-[10px] bg-[#1f5b43] px-4 py-2 text-xs font-semibold text-white"
293→                  >
294→                    저장
295→                  </button>
296→                </td>
297→              </tr>
298→            ))}
299→          </tbody>
300→        </table>
301→      </div>
302→    </div>
303→  );
304→}
