 13→export function AdminWorkflowTable({ columns, initialRows }: AdminWorkflowTableProps) {
 14→  const [rows, setRows] = useState(initialRows);
 15→  const [message, setMessage] = useState("");
 16→  const [savingAll, setSavingAll] = useState(false);
 17→  const [dirtyIds, setDirtyIds] = useState<number[]>([]);
 18→  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});
 19→
 20→  function markDirty(requestId: number) {
 21→    setDirtyIds((current) => (current.includes(requestId) ? current : [...current, requestId]));
 22→  }
 23→
 24→  function updateCell(rowIndex: number, columnKey: string, value: string) {
 25→    setRows((current) =>
 26→      current.map((item, index) =>
 27→        index === rowIndex
 28→          ? {
 29→              ...item,
 30→              values: { ...item.values, [columnKey]: value },
 31→            }
 32→          : item,
 33→      ),
 34→    );
 35→    markDirty(rows[rowIndex].requestId);
 36→  }
 37→
 38→  function focusCell(rowIndex: number, columnIndex: number) {
 39→    cellRefs.current[`${rowIndex}:${columnIndex}`]?.focus();
 40→  }
 41→
 42→  function handlePaste(
 43→    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 44→    rowIndex: number,
 45→    columnIndex: number,
 46→  ) {
 47→    const text = event.clipboardData.getData("text");
 48→    if (!text.includes("\t") && !text.includes("\n")) return;
 49→
 50→    event.preventDefault();
 51→    const matrix = text
 52→      .replace(/\r/g, "")
 53→      .split("\n")
 54→      .filter((line) => line.length > 0)
 55→      .map((line) => line.split("\t"));
 56→
 57→    setRows((current) =>
 58→      current.map((row, currentRowIndex) => {
 59→        const pastedRow = matrix[currentRowIndex - rowIndex];
 60→        if (!pastedRow) return row;
 61→
 62→        const values = { ...row.values };
 63→        pastedRow.forEach((cellValue, offset) => {
 64→          const column = columns[columnIndex + offset];
 65→          if (!column) return;
 66→          values[column.key] = cellValue;
 67→        });
 68→
 69→        return { ...row, values };
 70→      }),
 71→    );
 72→
 73→    const touchedIds = matrix
 74→      .map((_, offset) => rows[rowIndex + offset]?.requestId)
 75→      .filter((value): value is number => Boolean(value));
 76→    setDirtyIds((current) => [...new Set([...current, ...touchedIds])]);
 77→  }
 78→
 79→  function handleKeyDown(
 80→    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
 81→    rowIndex: number,
 82→    columnIndex: number,
 83→  ) {
 84→    if (event.key === "ArrowRight") {
 85→      event.preventDefault();
 86→      focusCell(rowIndex, Math.min(columnIndex + 1, columns.length - 1));
 87→    } else if (event.key === "ArrowLeft") {
 88→      event.preventDefault();
 89→      focusCell(rowIndex, Math.max(columnIndex - 1, 0));
 90→    } else if (event.key === "ArrowDown") {
 91→      event.preventDefault();
 92→      focusCell(Math.min(rowIndex + 1, rows.length - 1), columnIndex);
 93→    } else if (event.key === "ArrowUp") {
 94→      event.preventDefault();
 95→      focusCell(Math.max(rowIndex - 1, 0), columnIndex);
 96→    } else if (event.key === "Tab" && !event.shiftKey) {
 97→      event.preventDefault();
 98→      const nextColumnIndex = columnIndex + 1;
 99→      if (nextColumnIndex < columns.length) {
100→        focusCell(rowIndex, nextColumnIndex);
101→      } else if (rowIndex < rows.length - 1) {
102→        focusCell(rowIndex + 1, 0);
103→      }
104→    } else if (event.key === "Tab" && event.shiftKey) {
105→      event.preventDefault();
106→      const prevColumnIndex = columnIndex - 1;
107→      if (prevColumnIndex >= 0) {
108→        focusCell(rowIndex, prevColumnIndex);
109→      } else if (rowIndex > 0) {
110→        focusCell(rowIndex - 1, columns.length - 1);
111→      }
112→    }
