1071→export function getAdminWorkflowMatrix(): AdminWorkflowMatrix {
1072→  const db = getDb();
1073→  const requests = db
1074→    .prepare(
1075→      `SELECT
1076→        r.id as requestId,
1077→        d.college as college,
1078→        d.dept_name as deptName,
1079→        r.field_name as fieldName,
1080→        r.hiring_type as hiringType,
1081→        r.status as currentStatus,
1082→        r.priority as priority
1083→      FROM recruitment_requests r
1084→      JOIN departments d ON d.dept_code = r.dept_code
1085→      WHERE r.is_active = 1
1086→      ORDER BY d.college ASC, d.dept_name ASC, CAST(r.priority AS INTEGER) ASC, r.id ASC`,
1087→    )
1088→    .all() as Array<{
1089→    requestId: number;
1090→    college: string;
1091→    deptName: string;
1092→    fieldName: string;
1093→    hiringType: string;
1094→    currentStatus: string;
1095→    priority: string | null;
1096→  }>;
1097→
1098→  const submissions = getDb()
1099→    .prepare(
1100→      `SELECT
1101→        request_id as requestId,
1102→        step_key as stepKey,
1103→        payload_json as payloadJson,
1104→        created_at as createdAt
1105→      FROM submission_data
1106→      ORDER BY created_at DESC, id DESC`,
1107→    )
1108→    .all() as Array<{
1109→    requestId: number;
1110→    stepKey: string;
1111→    payloadJson: string;
1112→    createdAt: string;
1113→  }>;
1114→
1115→  const latestByRequestStep = new Map<string, { payload: Record<string, string>; createdAt: string }>();
1116→  for (const submission of submissions) {
1117→    const key = `${submission.requestId}:${submission.stepKey}`;
1118→    if (!latestByRequestStep.has(key)) {
1119→      latestByRequestStep.set(key, {
1120→        payload: JSON.parse(submission.payloadJson) as Record<string, string>,
1121→        createdAt: submission.createdAt,
1122→      });
1123→    }
1124→  }
1125→
1126→  const columnMap = new Map<string, AdminWorkflowColumn>();
1127→  for (const workflow of Object.values(WORKFLOW_FORMS)) {
1128→    for (const step of Object.values(workflow)) {
1129→      for (const field of step.fields) {
1130→        const key = `${step.stepKey}__${field.name}`;
1131→        if (!columnMap.has(key)) {
1132→          columnMap.set(key, {
1133→            key,
1134→            stepKey: step.stepKey,
1135→            fieldName: field.name,
1136→            label: `${step.title} · ${field.label}`,
1137→            inputType: field.type,
1138→            required: field.required,
1139→          });
1140→        }
1141→      }
1142→    }
1143→  }
1144→
1145→  const columns = [...columnMap.values()];
1146→
1147→  const rows = requests.map((request) => {
1148→    const procedureType = getProcedureType(request.hiringType);
1149→    const steps = PROCEDURE_STEPS[procedureType];
1150→    const values: Record<string, string> = {};
1151→    const updatedAtByStep: Record<string, string | null> = {};
1152→
1153→    for (const step of steps) {
1154→      const stepFields = WORKFLOW_FORMS[procedureType][step.stepKey]?.fields ?? [];
1155→      const submission = latestByRequestStep.get(`${request.requestId}:${step.stepKey}`);
1156→      updatedAtByStep[step.stepKey] = submission?.createdAt ?? null;
1157→
1158→      for (const field of stepFields) {
1159→        values[`${step.stepKey}__${field.name}`] = submission?.payload[field.name] ?? "";
1160→      }
1161→    }
1162→
1163→    return {
1164→      requestId: request.requestId,
1165→      college: request.college,
1166→      deptName: request.deptName,
1167→      fieldName: request.fieldName,
1168→      hiringType: request.hiringType,
1169→      currentStatus: request.currentStatus,
1170→      values,
1171→      updatedAtByStep,
1172→    };
1173→  });
1174→
1175→  return { columns, rows };
1176→}
