1178→export function upsertAdminWorkflowPayload(
1179→  requestId: number,
1180→  stepKey: string,
1181→  payloadJson: string,
1182→) {
1183→  const db = getDb();
1184→  const request = db
1185→    .prepare(`SELECT id, hiring_type as hiringType, status FROM recruitment_requests WHERE id = ?`)
1186→    .get(requestId) as { id: number; hiringType: string; status: string } | undefined;
1187→  if (!request) return null;
1188→
1189→  const existing = db
1190→    .prepare(
1191→      `SELECT id
1192→       FROM submission_data
1193→       WHERE request_id = ? AND step_key = ?
1194→       ORDER BY created_at DESC, id DESC
1195→       LIMIT 1`,
1196→    )
1197→    .get(requestId, stepKey) as { id: number } | undefined;
1198→
1199→  if (existing) {
1200→    db.prepare(
1201→      `UPDATE submission_data
1202→       SET payload_json = ?, updated_at = CURRENT_TIMESTAMP
1203→       WHERE id = ?`,
1204→    ).run(payloadJson, existing.id);
1205→  } else {
1206→    db.prepare(
1207→      `INSERT INTO submission_data (
1208→        request_id, submitted_by, procedure_type, step_key, status_before, status_after, payload_json
1209→      ) VALUES (?, 1, ?, ?, ?, NULL, ?)`,
1210→    ).run(requestId, getProcedureType(request.hiringType), stepKey, request.status, payloadJson);
1211→  }
1212→
1213→  return true;
1214→}
