export function getUnifiedDataSheet(): UnifiedDataSheet {
  const requestRows = getAdminRequestSheet();
  const { columns, rows: workflowRows } = getAdminWorkflowMatrix();

  const workflowByRequestId = new Map<
    number,
    { values: Record<string, string>; updatedAtByStep: Record<string, string | null>; currentStatus: string }
  >();
  for (const wRow of workflowRows) {
    workflowByRequestId.set(wRow.requestId, {
      values: wRow.values,
      updatedAtByStep: wRow.updatedAtByStep,
      currentStatus: wRow.currentStatus,
    });
  }

  const rows: UnifiedDataRow[] = requestRows.map((rRow) => {
    const wData = workflowByRequestId.get(rRow.requestId);
    return {
      ...rRow,
      currentStatus: wData?.currentStatus ?? rRow.status,
      workflowValues: wData?.values ?? {},
      workflowUpdatedAt: wData?.updatedAtByStep ?? {},
    };
  });

  return { columns, rows };
}

