"use client";

import Link from "next/link";
import { useRef, useState } from "react";
import { Download, Save, Upload } from "lucide-react";
import type { AdminWorkflowColumn, UnifiedDataRow } from "@/lib/types";

type UnifiedDataSheetProps = {
  columns: AdminWorkflowColumn[];
  initialRows: UnifiedDataRow[];
};

/* ── request-sheet editable columns (left/middle section) ── */
const REQUEST_COLUMNS: Array<{
  key: keyof Omit<UnifiedDataRow, "requestId" | "college" | "deptName" | "workflowValues" | "workflowUpdatedAt" | "currentStatus">;
  label: string;
  multiline?: boolean;
}> = [
  { key: "fieldName", label: "(최종) 초빙분야" },
  { key: "hiringType", label: "채용구분" },
  { key: "priority", label: "우선순위" },
  { key: "requestedCount", label: "요청 인원" },
  { key: "allocationResult", label: "배정 인원" },
  { key: "status", label: "현재 단계" },
  { key: "nextAction", label: "현재 필요 조치", multiline: true },
  { key: "requestedGeneral", label: "요청 일반" },
  { key: "requestedDedicated", label: "요청 전담" },
  { key: "requestedForeign", label: "요청 외" },
  { key: "kriFieldName", label: "KRI 분야", multiline: true },
  { key: "hiringReason", label: "채용 사유", multiline: true },
  { key: "deptRequestReason", label: "학과 요청 사유", multiline: true },
  { key: "subjectAssignment", label: "과목 배정", multiline: true },
  { key: "meetingNotes", label: "회의 메모", multiline: true },
  { key: "notes", label: "비고", multiline: true },
];

function buildRequestPayload(row: UnifiedDataRow) {
  return {
    fieldName: row.fieldName,
    hiringType: row.hiringType,
    priority: row.priority,
    requestedCount: row.requestedCount,
    allocationResult: row.allocationResult,
    status: row.status,
    nextAction: row.nextAction,
    requestedGeneral: row.requestedGeneral,
    requestedDedicated: row.requestedDedicated,
    requestedForeign: row.requestedForeign,
    kriFieldName: row.kriFieldName,
    hiringReason: row.hiringReason,
    deptRequestReason: row.deptRequestReason,
    subjectAssignment: row.subjectAssignment,
    meetingNotes: row.meetingNotes,
    notes: row.notes,
  };
}

export function UnifiedDataSheet({ columns: workflowColumns, initialRows }: UnifiedDataSheetProps) {
  const [rows, setRows] = useState(initialRows);
  const [message, setMessage] = useState("");
  const [uploading, setUploading] = useState(false);
  const [savingAll, setSavingAll] = useState(false);
  const [dirtyRequestIds, setDirtyRequestIds] = useState<number[]>([]);
  const [dirtyWorkflowIds, setDirtyWorkflowIds] = useState<number[]>([]);
  const cellRefs = useRef<Record<string, HTMLInputElement | HTMLTextAreaElement | null>>({});

  /* total column count: 2 fixed + REQUEST_COLUMNS + workflowColumns + 1 action */
  const totalReqCols = REQUEST_COLUMNS.length;
  const totalWfCols = workflowColumns.length;

  function markDirtyRequest(requestId: number) {
    setDirtyRequestIds((c) => (c.includes(requestId) ? c : [...c, requestId]));
  }
  function markDirtyWorkflow(requestId: number) {
    setDirtyWorkflowIds((c) => (c.includes(requestId) ? c : [...c, requestId]));
  }

  /* ── cell update helpers ── */
  function updateRequestCell(rowIndex: number, key: (typeof REQUEST_COLUMNS)[number]["key"], value: string) {
    setRows((current) =>
      current.map((item, i) => (i === rowIndex ? { ...item, [key]: value } : item)),
    );
    markDirtyRequest(rows[rowIndex].requestId);
  }

  function updateWorkflowCell(rowIndex: number, columnKey: string, value: string) {
    setRows((current) =>
      current.map((item, i) =>
        i === rowIndex
          ? { ...item, workflowValues: { ...item.workflowValues, [columnKey]: value } }
          : item,
      ),
    );
    markDirtyWorkflow(rows[rowIndex].requestId);
  }

  /* ── navigation ── */
  const totalEditableCols = totalReqCols + totalWfCols;

  function focusCell(rowIndex: number, colIndex: number) {
    cellRefs.current[`${rowIndex}:${colIndex}`]?.focus();
  }

  function handleKeyDown(
    event: React.KeyboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    colIndex: number,
  ) {
    if (event.key === "ArrowRight") {
      event.preventDefault();
      focusCell(rowIndex, Math.min(colIndex + 1, totalEditableCols - 1));
    } else if (event.key === "ArrowLeft") {
      event.preventDefault();
      focusCell(rowIndex, Math.max(colIndex - 1, 0));
    } else if (event.key === "ArrowDown") {
      event.preventDefault();
      focusCell(Math.min(rowIndex + 1, rows.length - 1), colIndex);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      focusCell(Math.max(rowIndex - 1, 0), colIndex);
    } else if (event.key === "Tab" && !event.shiftKey) {
      event.preventDefault();
      const next = colIndex + 1;
      if (next < totalEditableCols) {
        focusCell(rowIndex, next);
      } else if (rowIndex < rows.length - 1) {
        focusCell(rowIndex + 1, 0);
      }
    } else if (event.key === "Tab" && event.shiftKey) {
      event.preventDefault();
      const prev = colIndex - 1;
      if (prev >= 0) {
        focusCell(rowIndex, prev);
      } else if (rowIndex > 0) {
        focusCell(rowIndex - 1, totalEditableCols - 1);
      }
    }
  }

  /* ── paste ── */
  function handlePaste(
    event: React.ClipboardEvent<HTMLInputElement | HTMLTextAreaElement>,
    rowIndex: number,
    colIndex: number,
  ) {
    const text = event.clipboardData.getData("text");
    if (!text.includes("\t") && !text.includes("\n")) return;
    event.preventDefault();

    const matrix = text
      .replace(/\r/g, "")
      .split("\n")
      .filter((l) => l.length > 0)
      .map((l) => l.split("\t"));

    setRows((current) =>
      current.map((row, ri) => {
        const pastedRow = matrix[ri - rowIndex];
        if (!pastedRow) return row;

        const nextRow = { ...row, workflowValues: { ...row.workflowValues } };
        pastedRow.forEach((cellValue, offset) => {
          const ci = colIndex + offset;
          if (ci < totalReqCols) {
            const col = REQUEST_COLUMNS[ci];
            if (col) (nextRow as Record<string, unknown>)[col.key] = cellValue;
          } else {
            const wci = ci - totalReqCols;
            const wCol = workflowColumns[wci];
            if (wCol) nextRow.workflowValues[wCol.key] = cellValue;
          }
        });
        return nextRow;
      }),
    );

    const touchedIds = matrix
      .map((_, offset) => rows[rowIndex + offset]?.requestId)
      .filter((v): v is number => Boolean(v));

    /* determine which save targets are dirty */
    matrix.forEach((pastedRow, rowOffset) => {
      pastedRow.forEach((_, offset) => {
        const ci = colIndex + offset;
        const rid = rows[rowIndex + rowOffset]?.requestId;
        if (!rid) return;
        if (ci < totalReqCols) markDirtyRequest(rid);
        else markDirtyWorkflow(rid);
      });
    });

    setDirtyRequestIds((c) => [...new Set([...c, ...touchedIds.filter((id) => c.includes(id) || true)])]);
  }

  /* ── save ── */
  async function handleSaveRow(rowIndex: number) {
    const row = rows[rowIndex];
    const results: boolean[] = [];

    /* save request fields if dirty */
    if (dirtyRequestIds.includes(row.requestId)) {
      const res = await fetch("/api/admin/request-sheet", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ requestId: row.requestId, values: buildRequestPayload(row) }),
      });
      results.push(res.ok);
      if (res.ok) setDirtyRequestIds((c) => c.filter((id) => id !== row.requestId));
    }

    /* save workflow fields if dirty */
    if (dirtyWorkflowIds.includes(row.requestId)) {
      const res = await fetch("/api/admin/workflow", {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ requestId: row.requestId, values: row.workflowValues }),
      });
      results.push(res.ok);
      if (res.ok) setDirtyWorkflowIds((c) => c.filter((id) => id !== row.requestId));
    }

    if (results.length === 0) {
      setMessage("저장할 변경 사항이 없습니다.");
    } else if (results.every(Boolean)) {
      setMessage("저장했습니다.");
    } else {
      setMessage("일부 저장에 실패했습니다.");
    }
  }

  async function handleSaveAll() {
    const allDirty = [...new Set([...dirtyRequestIds, ...dirtyWorkflowIds])];
    if (!allDirty.length) {
      setMessage("저장할 변경 사항이 없습니다.");
      return;
    }
    setSavingAll(true);
    for (const rid of allDirty) {
      const ri = rows.findIndex((r) => r.requestId === rid);
      if (ri !== -1) await handleSaveRow(ri);
    }
    setSavingAll(false);
    setMessage("변경한 항목을 모두 저장했습니다.");
  }

  async function handleImport(event: React.ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0];
    if (!file) return;
    setUploading(true);
    const formData = new FormData();
    formData.set("file", file);
    const res = await fetch("/api/admin/request-sheet/import", { method: "POST", body: formData });
    const data = (await res.json().catch(() => ({}))) as { message?: string; count?: number };
    if (res.ok) {
      setMessage(`엑셀 업로드를 반영했습니다. ${data.count ?? 0}개 항목을 갱신했습니다.`);
      window.location.reload();
      return;
    }
    setMessage(data.message ?? "엑셀 업로드에 실패했습니다.");
    setUploading(false);
  }

  const totalDirty = new Set([...dirtyRequestIds, ...dirtyWorkflowIds]).size;

  /* ── min-width: 2 fixed(220 each) + reqCols(220 each) + wfCols(220 each) + action(180) ── */
  const tableMinWidth = 220 * 2 + totalReqCols * 220 + totalWfCols * 220 + 180;

  return (
    <div>
      {/* toolbar */}
      <div className="mb-4 flex flex-wrap items-center justify-between gap-3">
        <div className="flex flex-wrap gap-2">
          <button
            type="button"
            onClick={() => window.location.assign("/api/admin/request-sheet/export")}
            className="inline-flex items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-sm text-[#374151]"
          >
            <Download className="h-4 w-4" />
            엑셀 다운로드
          </button>
          <label className="inline-flex cursor-pointer items-center gap-2 rounded-[10px] border border-[#e5e7eb] bg-[#f9fafb] px-4 py-2 text-sm text-[#374151]">
            <Upload className="h-4 w-4" />
            {uploading ? "업로드 중..." : "엑셀 업로드"}
            <input type="file" accept=".xlsx,.xls,.csv" className="hidden" onChange={handleImport} />
          </label>
          <button
            type="button"
            onClick={handleSaveAll}
            disabled={savingAll}
            className="inline-flex items-center gap-2 rounded-[10px] border border-[#6a7f48] bg-[#394727] px-4 py-2 text-sm text-[#f3f1d4] disabled:opacity-60"
          >
            <Save className="h-4 w-4" />
            {savingAll ? "일괄 저장 중..." : `변경행 일괄 저장 (${totalDirty})`}
          </button>
        </div>
        <p className="text-sm text-[#6b7280]">
          엑셀이나 구글시트에서 범위를 복사해 붙여넣으면 여러 칸을 한 번에 반영할 수 있습니다.
        </p>
      </div>

      {message ? (
        <p className="mb-4 rounded-[10px] bg-[#f0f9f4] px-4 py-3 text-sm text-[#374151]">{message}</p>
      ) : null}

      <div className="max-h-[72vh] overflow-auto">
        <table
          className="border-separate border-spacing-0 text-sm"
          style={{ minWidth: tableMinWidth }}
        >
          <thead>
            <tr>
              {/* fixed cols */}
              <th
                className="sticky left-0 top-0 z-[15] border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                style={{ minWidth: 220 }}
              >
                소속대학
              </th>
              <th
                className="sticky top-0 z-[10] border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                style={{ minWidth: 220 }}
              >
                학과명
              </th>

              {/* request columns */}
              {REQUEST_COLUMNS.map((col) => (
                <th
                  key={col.key}
                  className="sticky top-0 z-[10] border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                  style={{ minWidth: 220 }}
                >
                  {col.label}
                </th>
              ))}

              {/* workflow columns */}
              {workflowColumns.map((col) => (
                <th
                  key={col.key}
                  className="sticky top-0 z-[10] border-b border-r border-[#e5e7eb] bg-[#f3f4f6] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                  style={{ minWidth: 220 }}
                >
                  <span className="block text-xs text-[#6b7280]">{col.stepKey}</span>
                  <span className="mt-1 block whitespace-pre-wrap">{col.label}</span>
                </th>
              ))}

              {/* action col */}
              <th
                className="sticky top-0 z-[10] border-b border-r border-[#e5e7eb] bg-[#f9fafb] px-4 py-4 text-center align-middle font-semibold text-[#111827]"
                style={{ minWidth: 180 }}
              >
                작업
              </th>
            </tr>
          </thead>
          <tbody>
            {rows.map((row, rowIndex) => {
              const stripe = rowIndex % 2 === 0 ? "bg-white" : "bg-[#f9fafb]";
              return (
                <tr key={row.requestId} className={stripe}>
                  {/* fixed: college */}
                  <td
                    className={`sticky left-0 z-[5] border-b border-r border-[#f0f0f0] px-4 py-3 ${stripe}`}
                  >
                    {row.college}
                  </td>
                  {/* dept */}
                  <td className="border-b border-r border-[#f0f0f0] px-4 py-3">{row.deptName}</td>

                  {/* request editable cells */}
                  {REQUEST_COLUMNS.map((col, ci) => (
                    <td
                      key={`${row.requestId}-req-${col.key}`}
                      className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top"
                    >
                      {col.multiline ? (
                        <textarea
                          ref={(node) => {
                            cellRefs.current[`${rowIndex}:${ci}`] = node;
                          }}
                          rows={4}
                          value={String((row as Record<string, unknown>)[col.key] ?? "")}
                          onChange={(e) => updateRequestCell(rowIndex, col.key, e.target.value)}
                          onPaste={(e) => handlePaste(e, rowIndex, ci)}
                          onKeyDown={(e) => handleKeyDown(e, rowIndex, ci)}
                          className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
                        />
                      ) : (
                        <input
                          ref={(node) => {
                            cellRefs.current[`${rowIndex}:${ci}`] = node;
                          }}
                          type="text"
                          value={String((row as Record<string, unknown>)[col.key] ?? "")}
                          onChange={(e) => updateRequestCell(rowIndex, col.key, e.target.value)}
                          onPaste={(e) => handlePaste(e, rowIndex, ci)}
                          onKeyDown={(e) => handleKeyDown(e, rowIndex, ci)}
                          className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
                        />
                      )}
                    </td>
                  ))}

                  {/* workflow editable cells */}
                  {workflowColumns.map((wCol, wci) => {
                    const globalCi = totalReqCols + wci;
                    return (
                      <td
                        key={`${row.requestId}-wf-${wCol.key}`}
                        className="border-b border-r border-[#f0f0f0] px-3 py-3 align-top"
                      >
                        {wCol.inputType === "textarea" ? (
                          <textarea
                            ref={(node) => {
                              cellRefs.current[`${rowIndex}:${globalCi}`] = node;
                            }}
                            rows={4}
                            value={row.workflowValues[wCol.key] ?? ""}
                            onChange={(e) => updateWorkflowCell(rowIndex, wCol.key, e.target.value)}
                            onPaste={(e) => handlePaste(e, rowIndex, globalCi)}
                            onKeyDown={(e) => handleKeyDown(e, rowIndex, globalCi)}
                            className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs leading-6 text-[#111827] outline-none focus:border-[#7fb18f]"
                          />
                        ) : (
                          <input
                            ref={(node) => {
                              cellRefs.current[`${rowIndex}:${globalCi}`] = node;
                            }}
                            type={wCol.inputType === "date" ? "text" : wCol.inputType}
                            value={row.workflowValues[wCol.key] ?? ""}
                            onChange={(e) => updateWorkflowCell(rowIndex, wCol.key, e.target.value)}
                            onPaste={(e) => handlePaste(e, rowIndex, globalCi)}
                            onKeyDown={(e) => handleKeyDown(e, rowIndex, globalCi)}
                            placeholder={wCol.inputType === "date" ? "YYYY-MM-DD" : ""}
                            className="w-full min-w-[200px] rounded-[10px] border border-[#e5e7eb] bg-white px-3 py-2 text-xs text-[#111827] outline-none focus:border-[#7fb18f]"
                          />
                        )}
                      </td>
                    );
                  })}

                  {/* action column */}
                  <td className="border-b border-r border-[#f0f0f0] px-4 py-3 text-center">
                    <div className="flex min-w-[160px] flex-col items-center gap-2">
                      <button
                        type="button"
                        onClick={() => handleSaveRow(rowIndex)}
                        className="rounded-[10px] bg-[#1f5b43] px-4 py-2 text-xs font-semibold text-white"
                      >
                        저장
                      </button>
                      <Link
                        href={`/procedures/${row.requestId}`}
                        className="rounded-[10px] border border-[#e5e7eb] bg-white px-4 py-2 text-xs font-semibold text-[#374151]"
                      >
                        절차 상세
                      </Link>
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { requireUser } from "@/lib/auth";
import { checkPermission } from "@/lib/permissions";
import { redirect } from "next/navigation";
import { getUnifiedDataSheet } from "@/lib/queries";
import { UnifiedDataSheet } from "@/components/unified-data-sheet";

export default async function DataPage() {
  const user = await requireUser();
  if (!checkPermission(user.role, "admin.data", "view")) {
    redirect("/dashboard");
  }

  const { columns, rows } = getUnifiedDataSheet();

  return (
    <div>
      <div style={{ marginBottom: 20 }}>
        <h2 style={{ fontSize: 18, fontWeight: 600, color: "#111", margin: 0 }}>데이터 관리</h2>
        <p style={{ fontSize: 12, color: "#888", margin: "2px 0 0" }}>
          채용요청 데이터와 워크플로우를 통합 관리합니다
        </p>
      </div>

      <section>
        <UnifiedDataSheet columns={columns} initialRows={rows} />
      </section>
    </div>
  );
}
